from pathlib import Path
import json
R=Path(__file__).resolve().parents[1];D='2026-10-30'
def wr(p,d):(R/p).write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
segments=[
('BS01','Payroll technology','Product, positioning or route-to-market decision about a defined payroll buyer and operating problem.','A scoped case comparison and briefing may clarify needs, objections and evidence used in decisions.','Internal product/commercial decision support; separate permission if using material in marketing.','Cannot infer adoption rate, software market share, product preference, conversion or an addressable lead list.'),
('BS02','Payroll outsourcing/services','Define service boundaries, retained employer work, transition support or evidence for a specific proposition.','Case context may help distinguish the work a buyer needs from a generic outsourcing label.','Internal service design/use; external sales collateral is a separate use.','No supplier endorsement, outsourced-service ranking, probability of switching or buyer contacts.'),
('BS03','HCM organisations','Choose a payroll integration, delivery or adjacent proposition and its actual buyer context.','A clearly scoped payroll decision lens may complement wider HCM material.','Internal strategy/product use; separately defined excerpts or client-use rights if wanted.','No generalisation from payroll-only cases to all HR technology or every geography.'),
('BS04','Consulting/advisory','Prepare a client decision brief or improve a repeatable advisory method for a defined payroll problem.','An evidence-based synthesis or framework might reduce duplicated discovery or expose missing evidence. That usefulness is untested.','Named client-facing deliverable/quotation/redistribution must be distinguished from internal reading.','Not an automatic sublicence, client-data submission, commissioned due diligence or bespoke consulting service.'),
('BS05','Investment organisations','Orient sector research or test an investment thesis about payroll operating needs and buying constraints.','Scoped qualitative context can identify questions for later diligence.','Internal research use; external portfolio/client circulation separately specified where relevant.','Not investment advice, deal due diligence, valuation, total market estimate, purchase forecast or company scoring.'),
('BS06','Employer decision user, additional hypothesis','Support an actual payroll investment, change, renewal or operating decision.','An application briefing or genuinely additional use may be useful beyond the free research received by a practitioner contributor.','First establish already granted free access and actual incremental service/use; do not manufacture restrictions.','Not a contract-prioritised primary buyer or a presumed second paid report copy.')]
wr('04-table/T02-buyer-segments.json',dict(date=D,status='internal_segment_use_hypotheses_not_customer_research',contract_segment_ids=['BS01','BS02','BS03','BS04','BS05'],additional_segment_ids=['BS06'],ranked=False,records=[dict(segment_id=i,segment=n,possible_job=j,possible_output_value=v,intended_use_and_rights_to_establish=r,limits=l,actual_payer_identified=False,actual_purchase_observed=False,validated=False)for i,n,j,v,r,l in segments],source_basis=['Signed-project working agreement section5 target-market design input','T01/T01second primary offer comparisons are analogies only'],canonical_claim_ids=['CLM-0506','CLM-0507','CLM-0515','CLM-0516','CLM-0522'],actual_buyers=[],price_estimates=[]))
rights=[
('RU01','Contributor research','Preserve the research free to participating practitioners, as in the original concept.','Do not downgrade this to a teaser or invent individual-only restrictions to force a sale. Actual use boundaries must be discussed rather than presumed.','Existing concept benefit; precise later terms remain to be agreed.'),
('RU02','Employer/internal team use','Specify the report/version and actual intended internal circulation or decision use where a paid proposition is useful.','First check overlap with contributor access and what genuinely additional entitlement/service is wanted.','Proposed customer-use definition; no right granted or price set.'),
('RU03','Public excerpt/marketing use','Define exact original material, attribution, channel, period and permitted alterations if the customer wants external use.','No third-party chart/report, participant identity, quote or implied endorsement included merely because JGA owns commissioned analysis.','Proposed option requiring content-level rights and later customer terms.'),
('RU04','Adviser client deliverable','Identify whether use is internal preparation, quotation in a client deliverable, client access to the report or wider resale.','No blanket sublicensing/client redistribution assumed; also do not declare it forbidden before JGA decides terms and underlying rights permit.','Open product-use choice, not a Riseklix veto over JGA work.'),
('RU05','Briefing/application service','Define actual audience, agenda, preparation, duration/capacity and follow-up if a briefing is part of the offer.','Not unlimited analyst inquiry, payroll compliance helpdesk, custom research, investment advice or recurring support.','Candidate servicing work to test and cost, not a contracted commitment.'),
('RU06','Partner recognition','Describe the specific disclosed recognition and agreed research output/use.','No implied research endorsement, conclusion control, guaranteed return or unagreed exclusivity.','Candidate funding benefits; editorial/rights terms remain open.'),
('RU07','Optional commercial access','If requested, define a separate transparent access benefit and test participant fit/permissions and delivery capacity.','Research funding does not provide default contacts, individual answers, meeting lists or introductions. No actual access promised.','Potential separate combination, not included in the minimum draft.'),
('RU08','Updates/later editions','Specify the actual version/date of outputs. Assess whether later refreshes are wanted and economically deliverable.','No implied subscription, auto-renewal, future council tenure or indefinite updates from an annual concept.','Later scope/price decision; not part of current draft service.')]
wr('04-table/T02-use-and-entitlement-options.json',dict(date=D,status='product_design_options_not_licence_terms',actual_rights_grants=[],actual_customer_contracts=[],Riseklix_controls_JGA_commissioned_IP=False,ownership_note='The working agreement assigns commissioned IP to JGA after full payment, with broad exploitation rights subject to participant/third-party constraints. These future customer-use options do not reserve a new Riseklix veto or amend that agreement.',options=[dict(option_id=i,use=n,definition=t,boundary=b,state=st,approved=False)for i,n,t,b,st in rights],canonical_support_ids=['CLM-0506','CLM-0515','CLM-0516','CLM-0518','CLM-0519','CLM-0522']))
lines=['# Buyer uses and product rights to define','', 'Internal T02 design, 30 October 2026. These are possible uses to test, not customers, prices or granted licences. Five segments come from the working agreement; employer-side use is an additional hypothesis.','', '| Possible buyer | Specific job to investigate | Possible useful output | Boundary |','| --- | --- | --- | --- |']
for i,n,j,v,r,l in segments:lines.append(f'| {n} | {j} | {v} | {l} |')
lines+=['','## Define the use before a price','','The same publication can serve different jobs. Do not price solely by organisation label. Establish the actual user, decision, available alternatives, intended internal/client/public use and practical delivery work. Buyer, budget owner and beneficiary may be different. A positive discussion or request for information is not a purchase.','', 'The first research edition can support scoped qualitative insight if actual permitted input supports it. It cannot sell a representative benchmark, market demand estimate, causal explanation or promise of commercial results. A gap in the evidence remains a useful finding; it must not be converted into a confident invented answer.','', '## Contributor access comes first','','The original concept gives practitioners the research free. Preserve that benefit. If an employer receives equivalent access through a contributor, do not forecast a second licence by assumption. Test whether additional circulation/use or a prepared decision briefing is actually valuable and deliverable. Do not silently narrow the free benefit to create a paid tier.','', '## Use options, not a legal agreement','', '| Use | What to define | Important boundary |','| --- | --- | --- |']
for i,n,t,b,st in rights:lines.append(f'| {i}: {n} | {t} | {b} |')
lines+=['', 'The working agreement gives JGA broad rights in commissioned assets after full payment, subject to underlying participant and third-party limits. Future customer licences are JGA product decisions; these options do not reserve new Riseklix ownership or an approval veto. Neither public competitor access nor attribution alone grants redistribution rights. Actual licences are prepared later with the relevant material and use specified.','', 'No fee, seat count, licence period, territorial exclusivity, renewal, distribution channel or analyst capacity has been agreed here. Use the [structured segment map](T02-buyer-segments.json) and [use options](T02-use-and-entitlement-options.json) for exact status and evidence links.']
(R/'04-table/T02-BUYER-USES-AND-RIGHTS.md').write_text('\n'.join(lines)+'\n')
